import { Component } from '@angular/core';

@Component({
  selector: 'app-my-functions',
  templateUrl: './my-functions.component.html',
  styleUrls: ['./my-functions.component.scss']
})
export class MyFunctionsComponent {
    snippet=`
    function functionName(){

      set of statements;

    }`;
    bracket=`{ }`;
    snippet1=`
    functionName(){

      set of statements;

    }`;
    type1Syntax=`
    functionName(){

      set of statements;

    }`;
    type1SyntaxArrow=`
    () => {

      set of statements;

    }`;
    type1Example=`
    addTwoNumbers(){
      let a=23;
      let b=45;
      let c=a+b;
      console.log(c);
    }`;

    type1ExampleArrow=`
    () => {
      let a=23;
      let b=45;
      let c=a+b;
      console.log(c);
    }`;
    type1CallingSyntax=`
    functionName();`;
    type1CallingExample=`
    addTwoNumbers();`;

    type2Syntax=`
    functionName(param-1, param-2, ........, param-n){

      set of statements;

      return value;

    }`;

    type2SyntaxArrow=`
    let output = (param-1, param-2, ........, param-n) => {

      set of statements;

      return value;

    }`;
    type2Example=`
    addTwoNumbers(a,b){

      let c=a+b;

     return c;

    }`;

    type2ExampleArrow=`
    let result = (a,b) => {

      let c=a+b;

     return c;

    }`;
    
    type2CallingSyntax=`
    let output=functionName(param-1, param-2, ........, param-n);`;
    type2CallingExample=`
    let result=addTwoNumbers(23 , 45);`;


    type3Syntax=`
    functionName(){

      set of statements;

      return value;

    }`;

    type3SyntaxArrow=`
    let output = () => {

      set of statements;

      return value;

    }`;
    type3Example=`
    addTwoNumbers(){
      let a=23;
      let b=45;
      let c=a+b;

     return c;

    }`;
    
    type3ExampleArrow=`
    let result = () => {
      let a=23;
      let b=45;
      let c=a+b;

     return c;

    }`;

    type3CallingSyntax=`
    let output=functionName();`;
    type3CallingExample=`
    let result=addTwoNumbers();`;

    type4Syntax=`
    functionName(param-1, param-2, ........, param-n){

      set of statements;


    }`;

    type4SyntaxArrow=`
    (param-1, param-2, ........, param-n) => {

      set of statements;


    }`;
    type4Example=`
    addTwoNumbers(a,b){

      let c=a+b;
      console.log(c);
     

    }`;
    
    type4ExampleArrow=`
    (a,b) => {

      let c=a+b;
      console.log(c);
     

    }`;

    type4CallingSyntax=`
    functionName(param-1, param-2, ........, param-n);`;
    type4CallingExample=`
    addTwoNumbers(23 , 45);`;

    arrowFunctionSyntax=`
    () => {

      set of statements;

    }
    `;

}
<h3>Function Definition</h3>
<p>Grouping of set of statements as a unit </p>
<b>syntax:-</b>
<pre>{{snippet}}</pre>
<p>Here function is called pre-defined keyword to indicate as a function.</p>
<p>functionName is the name of the function </p>
<p> {{bracket}} is called function block. Block means group of statements between the {{bracket}} </p>
<h3>Note</h3>
<p> Typescript and javascript are almost similar. But in typescript function keyword is not-required.So typescript function syntax is </p>
<pre>{{snippet1}}</pre>

<h3>Arrow function</h3>
<p> A function without function name is called "Arrow function". This function is not used for future purpose. It is used 
         directly where ever required </p>
<b>syntax:-</b>
<pre>{{arrowFunctionSyntax}}</pre>

<h3>Types of functions</h3>
<p>There are 4-types of functions </p>
<ol>
    <li> without parameters , without return value </li>
    <li> with parameters , with return value </li>
    <li> without parameters , with return value </li>
    <li> with parameters , without return value </li>
</ol>
<!-- =====================================Type-1============================================================= -->
<h3>Type-1: without parameters , without return value</h3>
<h4>Defining(writing) function </h4>
<b>syntax:-</b>
<pre>{{type1Syntax}}</pre>
<b>arrow funcion syntax:-</b>
<pre>{{type1SyntaxArrow}}</pre>
<b>Example</b>
<pre>{{type1Example}}</pre>
<b>arrow function example</b>
<pre>{{type1ExampleArrow}}</pre>
<h4>Calling(Executing(or)Accessing) function</h4>
<b>syntax:-</b>
<pre>{{type1CallingSyntax}}</pre>
<b>Example</b>
